package com.elogistic.backend.notifications.internal.application;

import com.elogistic.backend.notifications.api.BusinessReporting;
import com.elogistic.backend.orders.api.BusinessReportSources;
import com.elogistic.backend.orders.api.BusinessPreparations;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class BusinessReportingTests {
    private final BusinessReporting service=new BusinessReportingService();
    private static final UUID ORG=UUID.fromString("10000000-0000-4000-8000-000000000001"),ACTOR=UUID.fromString("10000000-0000-4000-8000-000000000002");
    private static final Instant NOW=Instant.parse("2026-11-15T05:00:00Z");
    private BusinessReportSources.Row row(String time,long amount,int parcels){var facts=new ArrayList<BusinessReportSources.Parcel>();var lines=new ArrayList<BusinessReportSources.Line>();for(int i=1;i<=parcels;i++){facts.add(new BusinessReportSources.Parcel(750));lines.add(new BusinessReportSources.Line(i,750,1000,i==1?amount:0));}UUID id=UUID.randomUUID();return new BusinessReportSources.Row(id,"AP-SIM-"+id.toString().replace("-",""),Instant.parse(time),null,ACTOR,"WEB","SOURCE",null,new BusinessReportSources.Quote(UUID.randomUUID(),ORG,1,"ARGO-ROAD-TARIFF-1",new BusinessReportSources.Route("SIM-A1","SIM-A2"),facts,lines,amount));}
    private BusinessReportSources.Cohort cohort(boolean money,List<BusinessReportSources.Row> rows){return new BusinessReportSources.Cohort(NOW,money,rows,new BusinessReportSources.Preparation("AVAILABLE",null,"4","2","1","1"),new BusinessReportSources.Activity("AVAILABLE",null,"4","1",List.of(new BusinessReportSources.Actor(ACTOR,"4","1"))));}
    @Test void wholeCohortKeepsShipmentParcelWeightFeesAndInternalGrainsDistinct(){
        var q=service.query(Map.of(),NOW,"OPERATIONS",false);var report=service.operations(ORG,q,cohort(true,List.of(row("2026-11-14T00:00:00Z",53000,2),row("2026-11-15T00:00:00Z",25000,1))));
        assertEquals("2",report.summary().shipments());assertEquals("3",report.summary().parcels());assertEquals("2250",report.summary().actualGrams());assertEquals("3000",report.summary().chargeableGrams());assertEquals("78000",report.summary().confirmedFeesVnd());assertEquals("4",report.preparations().total());assertEquals("4",report.activity().created());assertEquals(new BusinessReporting.Average("78000","2"),report.summary().averageFee());assertEquals("2",report.breakdowns().channel().getFirst().shipments());
    }
    @Test void financialPermissionAbsenceIsNullAndCannotBecomeAZeroOrFinanceReport(){var q=service.query(Map.of(),NOW,"OPERATIONS",false);var data=cohort(false,List.of(row("2026-11-14T00:00:00Z",53000,1)));var report=service.operations(ORG,q,data);assertEquals("FORBIDDEN",report.financialState());assertNull(report.summary().confirmedFeesVnd());assertNull(report.summary().averageFee());assertTrue(report.trend().stream().allMatch(b->b.confirmedFeesVnd()==null));assertNull(report.breakdowns().facility().getFirst().unpaidFeesVnd());assertThrows(IllegalStateException.class,()->service.finance(ORG,q,data));}
    @Test void emptySupportedCohortHasZeroBucketsButUnsupportedMetricsHaveNoNumbers(){var report=service.operations(ORG,service.query(Map.of(),NOW,"OPERATIONS",false),cohort(true,List.of()));assertEquals("0",report.summary().shipments());assertEquals("0",report.summary().confirmedFeesVnd());assertEquals(30,report.trend().size());assertTrue(report.trend().stream().allMatch(b->b.shipments().equals("0")));assertTrue(report.capabilities().stream().anyMatch(c->c.id().equals("COD")&&c.state().equals("NOT_SUPPORTED")));}
    @Test void vietnamMidnightAndMondayWeekBoundariesRemainDistinct(){var q=service.query(Map.of("from","2026-11-01","until","2026-11-15","interval","WEEK"),NOW,"OPERATIONS",false);var report=service.operations(ORG,q,cohort(true,List.of(row("2026-11-01T16:59:00Z",25000,1),row("2026-11-01T17:00:00Z",25000,1))));assertEquals(List.of("1","1","0"),report.trend().stream().map(BusinessReporting.Bucket::shipments).toList());assertEquals(LocalDate.parse("2026-11-02"),report.trend().get(1).from());assertTrue(report.trend().getFirst().partial());assertTrue(report.trend().getLast().partial());}
    @Test void quarterYearAndClippedTodayUseRealCalendarBoundaries(){Instant now=Instant.parse("2026-01-15T05:00:00Z");for(String interval:List.of("QUARTER","YEAR")){var q=service.query(Map.of("from","2025-12-20","until","2026-01-16","interval",interval),now,"OPERATIONS",false);var report=service.operations(ORG,q,new BusinessReportSources.Cohort(now,true,List.of(row("2025-12-31T17:00:00Z",25000,1)),null,null));assertEquals(2,report.trend().size());assertEquals(List.of("0","1"),report.trend().stream().map(BusinessReporting.Bucket::shipments).toList());assertTrue(report.trend().stream().allMatch(BusinessReporting.Bucket::partial));}}
    @Test void moneyRemainsExactBeyondLongAndJavascriptAggregationRanges(){var rows=List.of(row("2026-11-14T00:00:00Z",Long.MAX_VALUE,1),row("2026-11-15T00:00:00Z",Long.MAX_VALUE,1));var report=service.finance(ORG,service.query(Map.of(),NOW,"FINANCE",false),cohort(true,rows));assertEquals("18446744073709551614",report.summary().confirmedFeesVnd());assertEquals("0",report.summary().differenceVnd());assertEquals("2",report.total());}
    @Test void financePaginationNeverRedefinesSummaryOrDimensionCohort(){var rows=new ArrayList<BusinessReportSources.Row>();for(int i=0;i<21;i++)rows.add(row("2026-11-14T00:00:00Z",25000,1));var q=service.query(Map.of("page","1"),NOW,"FINANCE",false);var report=service.finance(ORG,q,cohort(true,rows));assertEquals(1,report.items().size());assertEquals("21",report.total());assertEquals("525000",report.summary().unpaidFeesVnd());assertFalse(report.hasNext());assertEquals("21",report.breakdowns().service().getFirst().shipments());}
    @Test void malformedUnknownSelectorAndOversizedPeriodAreRejected(){for(var p:List.of(Map.of("from","2026-02-30","until","2026-03-02"),Map.of("from","2024-01-01","until","2026-01-01"),Map.of("from","2026-01-01"),Map.of("interval","HOURLY"),Map.of("ownerId",ORG.toString()),Map.of("page","0")))assertThrows(BusinessPreparations.Failure.class,()->service.query(p,NOW,"OPERATIONS",false));assertThrows(BusinessPreparations.Failure.class,()->service.query(Map.of("page","0"),NOW,"FINANCE",true));}
    @Test void sourceChannelSentinelCannotCollideWithLiteralUnboundCode(){var first=row("2026-11-14T00:00:00Z",25000,1);var unbound=new BusinessReportSources.Row(first.shipmentId(),first.code(),first.createdAt(),null,ACTOR,null,null,null,first.quote());var named=new BusinessReportSources.Row(UUID.randomUUID(),"AP-SIM-synthetic",first.createdAt(),null,ACTOR,"UNBOUND","SOURCE",null,first.quote());var report=service.operations(ORG,service.query(Map.of(),NOW,"OPERATIONS",false),cohort(true,List.of(unbound,named)));assertEquals(List.of("CHANNEL:UNBOUND","UNBOUND"),report.breakdowns().channel().stream().map(BusinessReporting.Dimension::key).toList());}
    @Test void reportExportsHaveNoContactsAndForbiddenMoneyCellsAreEmpty(){var q=service.query(Map.of(),NOW,"OPERATIONS",true);var result=service.export(ORG,q,cohort(false,List.of(row("2026-11-14T00:00:00Z",25000,1))),"OPERATIONS","channel");assertFalse(result.columns().stream().anyMatch(c->c.toLowerCase(Locale.ROOT).matches(".*(recipient|sender|phone|email).*")));assertEquals("",result.rows().getFirst().get(9));assertEquals("1",result.rows().getFirst().get(5));}
    @Test void dimensionOverflowDeniesWholeReportInsteadOfTruncatingGroups(){var template=row("2026-11-14T00:00:00Z",25000,1);var rows=new ArrayList<BusinessReportSources.Row>();for(int i=0;i<1001;i++)rows.add(new BusinessReportSources.Row(UUID.randomUUID(),template.code(),template.createdAt(),null,ACTOR,"CHANNEL-"+i,"SOURCE",null,template.quote()));assertEquals("REPORT_LIMIT_EXCEEDED",assertThrows(BusinessPreparations.Failure.class,()->service.operations(ORG,service.query(Map.of(),NOW,"OPERATIONS",false),cohort(true,rows))).getMessage());}
}
